"""OpenDriver workflow evidence for the Windows platform.

A driver workflow ends with records the application holds: the driver account, the
saved profile, the documents that were submitted and the payout that followed.
This evaluator looks each of those up in the application's own store as a unique
record and compares it field by field against what the task requires.

Only the resulting records are compared.  The screens the agent visited, the
number of actions it took and the order in which the steps were performed are not
part of the decision.
"""

from __future__ import annotations

from typing import Any, Mapping

from evaluators.cua_review.core.evaluation import EvalResult, EvalStatus
from evaluators.cua_review.evaluators.windows.opendriver import (
    ID_KEYS,
    OpenDriverAccountEvaluator,
    _field,
    _normalise,
)


class OpenDriverEvidenceEvaluator(OpenDriverAccountEvaluator):
    """Decide an OpenDriver workflow from the records the application holds."""

    TASK_ID: str = ""

    def evaluate(self, context: Mapping[str, Any]) -> EvalResult:
        params = self._context_params(context)
        controller = context.get("controller")
        store = self.read_store(controller, int(params.get("db_read_timeout", 20)))
        nodes = self.nodes(store)
        checks: list[dict[str, Any]] = []

        def unique_matches(wanted: Mapping[str, Any]) -> list[dict[str, Any]]:
            found = []
            for _, node in nodes:
                if all(_normalise(_field(node, key)) == _normalise(value)
                       for key, value in wanted.items()):
                    found.append(node)
            return found

        for check_id, key, label in (
            ("account", "expected_account", "account"),
            ("profile", "expected_profile", "saved profile"),
            ("document", "expected_document", "submitted document"),
        ):
            wanted = dict(params.get(key) or {})
            if not wanted:
                continue
            matches = unique_matches(wanted)
            passed = len(matches) == 1
            checks.append({
                "check_id": check_id,
                "passed": passed,
                "expected": wanted,
                "observed": {"match_count": len(matches),
                             "ids": [self.scalar(row, ID_KEYS) for row in matches]},
                "failure_reason": "" if passed else
                f"the {label} the task requires is not held exactly once",
            })

        payout = dict(params.get("expected_payout") or {})
        if payout and params.get("require_payout_amount", True):
            amount = str(payout.get("amount") or "")
            matches = []
            for _, node in nodes:
                recorded = _field(node, "amount", "payoutAmount", "total")
                if recorded is None:
                    continue
                try:
                    if abs(float(recorded) - float(amount)) < 1e-9:
                        matches.append(node)
                except (TypeError, ValueError):
                    continue
            passed = bool(matches)
            checks.append({
                "check_id": "payout",
                "passed": passed,
                "expected": payout,
                "observed": {"match_count": len(matches)},
                "failure_reason": "" if passed else
                "the payout amount the task requires is not held",
            })

        if params.get("require_logged_out_sessions_empty"):
            count = self.count_sessions(store)
            checks.append({
                "check_id": "sessions_empty",
                "passed": count == 0,
                "expected": 0,
                "observed": count,
                "failure_reason": "" if count == 0 else "the application still holds a session",
            })

        failed = [row["check_id"] for row in checks if not row["passed"]]
        metadata = {
            "task_id": self.TASK_ID,
            "read_only": True,
            "database_path": store.get("database_path"),
            "checks": checks,
            "failed_checks": failed,
            "store_readable": bool(store.get("data") is not None),
        }
        if not checks:
            return EvalResult(status=EvalStatus.ERROR,
                              message="no record criteria declared", metadata=metadata)
        if failed:
            return EvalResult(status=EvalStatus.FAIL,
                              message="OpenDriver evaluation failed: " + ", ".join(failed),
                              metadata=metadata)
        return EvalResult(status=EvalStatus.PASS,
                          message="the records the task requires are held", metadata=metadata)
